test('retained initial lookup and last state support style refresh and missing-target recovery', () => {
  const data = owned(input()), view = presentation(), prepared = finish(workFor(data, view), 1).value.batch;
  const legacy = createGraphSpatialEdges(data); legacy.update(view, point(data), view.state);
  let missing = true; const lookup = row => row === 2 && missing ? null : point(data)(row);
  try {
    prepared.takeChanges(); legacy.takeChanges();
    data.positions[3] = 120;
    prepared.updateStyle(view, view.state); legacy.updateStyle(view, view.state);
    assert.deepEqual(snapshot(prepared), snapshot(legacy)); assert.equal(prepared.mesh.geometry.attributes.edgeEnd.getX(0), 120);
    prepared.updatePositions(view, lookup); legacy.updatePositions(view, lookup);
    assert.deepEqual(snapshot(prepared), snapshot(legacy)); assert.equal(prepared.mesh.geometry.attributes.stroke.getY(20), 0);
    missing = false;
    prepared.updateStyle(view, view.state); legacy.updateStyle(view, view.state);
    assert.deepEqual(snapshot(prepared), snapshot(legacy)); assert.equal(prepared.mesh.geometry.attributes.stroke.getY(20), 12);
  } finally { prepared.dispose(); legacy.dispose(); }
});

